interface SidebarNavButtonProps {
  id: string;
  onClick: () => void;
  active: boolean;
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  collapsed: boolean;
  unreadCount?: number;
  pulseAlert?: boolean;
  pulseLabel?: boolean;
  bubbleText?: string;
}

const SidebarNavButton: React.FC<SidebarNavButtonProps> = ({
  id,
  onClick,
  active,
  icon: Icon,
  label,
  collapsed,
  unreadCount = 0,
  pulseAlert = false,
  pulseLabel = false,
  bubbleText,
}) => {
  return (
    <div className="relative group w-full">
      <button
        id={id}
        onClick={onClick}
        className={`relative w-full flex items-center ${
          collapsed ? "justify-center px-0 py-3" : "gap-3 py-3 px-4"
        } rounded-xl cursor-pointer transition-all ${
          active
            ? "gradient-border-glow-tab-active bg-brand-accent text-white"
            : "hover:bg-brand-accent/20 text-brand-secondary/80 hover:text-white"
        }`}
      >
        <div className="relative flex items-center justify-center shrink-0">
          <Icon className="w-5 h-5" />
          {pulseAlert && (
            <span className="absolute -top-1 -right-1 flex h-3 w-3 z-10">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-rose-400 opacity-75" />
              <span className="relative inline-flex rounded-full h-3 w-3 bg-rose-500 border border-white" />
            </span>
          )}
          {collapsed && unreadCount > 0 && (
            <span className="absolute -top-0.5 -right-0.5 w-2 h-2 bg-rose-500 rounded-full border border-brand-primary animate-pulse" />
          )}
          {collapsed && bubbleText && (
            <span className="absolute -top-2 -right-2 z-20 px-1.5 py-0.5 rounded-full bg-emerald-500 text-white text-[8px] font-black shadow-md animate-bell-ring whitespace-nowrap">
              NEW
            </span>
          )}
        </div>
        {!collapsed && (
          <span className={`truncate ${pulseLabel ? "animate-pulse-red font-bold text-rose-500 dark:text-rose-400" : ""}`}>
            {label}
          </span>
        )}
        {!collapsed && bubbleText && (
          <span className="ml-auto px-2 py-0.5 rounded-full bg-emerald-500 text-white text-[9px] font-extrabold shadow-md animate-bell-ring whitespace-nowrap shrink-0 z-20">
            {bubbleText}
          </span>
        )}
        {!collapsed && unreadCount > 0 && !bubbleText && (
          <span className="ml-auto w-2 h-2 bg-rose-500 rounded-full" />
        )}
      </button>

      {collapsed && (
        <span className="sidebar-tooltip pointer-events-none absolute left-full ml-3 top-1/2 -translate-y-1/2 whitespace-nowrap rounded-lg bg-[#150B2E] text-white text-xs font-semibold px-3 py-1.5 shadow-lg opacity-0 group-hover:opacity-100 transition-opacity duration-150 z-50">
          {label}
        </span>
      )}
    </div>
  );
};

