let adminAudioCtx: AudioContext | null = null;
function getAdminAudioContext(): AudioContext | null {
  if (typeof window === "undefined") return null;
  if (!adminAudioCtx) {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioContextClass) {
      adminAudioCtx = new AudioContextClass();
    }
  }
  if (adminAudioCtx && adminAudioCtx.state === "suspended") {
    adminAudioCtx.resume().catch(() => {});
  }
  return adminAudioCtx;
}

  const playLoanNotificationSound = async () => {
    try {
      const ctx = getAdminAudioContext();
      if (!ctx) return;
      if (ctx.state === "suspended") {
        await ctx.resume().catch(() => {});
      }

      const now = ctx.currentTime;

      // Tone 1
      const osc1 = ctx.createOscillator();
      const gain1 = ctx.createGain();
      osc1.type = "sine";
      osc1.frequency.setValueAtTime(523.25, now); // C5
      osc1.frequency.exponentialRampToValueAtTime(659.25, now + 0.15); // E5
      gain1.gain.setValueAtTime(0.15, now);
      gain1.gain.exponentialRampToValueAtTime(0.01, now + 0.3);

      osc1.connect(gain1);
      gain1.connect(ctx.destination);
      osc1.start(now);
      osc1.stop(now + 0.3);

      // Tone 2 (delayed slightly)
      const osc2 = ctx.createOscillator();
      const gain2 = ctx.createGain();
      osc2.type = "sine";
      osc2.frequency.setValueAtTime(659.25, now + 0.15); // E5
      osc2.frequency.exponentialRampToValueAtTime(783.99, now + 0.3); // G5
      gain2.gain.setValueAtTime(0.15, now + 0.15);
      gain2.gain.exponentialRampToValueAtTime(0.01, now + 0.45);

      osc2.connect(gain2);
      gain2.connect(ctx.destination);
      osc2.start(now + 0.15);
      osc2.stop(now + 0.45);
    } catch (e) {
      console.warn("Audio Context could not start:", e);
    }
  };

  const playGeneralNotificationSound = async () => {
    try {
      const ctx = getAdminAudioContext();
      if (!ctx) return;
      if (ctx.state === "suspended") {
        await ctx.resume().catch(() => {});
      }

      const now = ctx.currentTime;

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(587.33, now); // D5
      osc.frequency.exponentialRampToValueAtTime(587.33, now + 0.15);
      gain.gain.setValueAtTime(0.1, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.15);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.15);
    } catch (e) {
      console.warn("Audio Context could not start:", e);
    }
  };

  const getCompanyMarginSum = () => {
    const now = new Date();
    const confirmedWithdrawals = allTxns.filter((tx) => {
      // 1. Must be withdrawal and confirmed
      if (tx.type !== "withdrawal" || tx.status !== "confirmed") {
        return false;
      }

      // 2. Branch filtering
      if (user.role === "pdg" || dbService.hasCompanyWideAccess(user, "view_company_margin")) {
        if (!selectedBranches.includes(tx.branch_id)) {
          return false;
        }
      } else {
        if (tx.branch_id !== user.branch_id) {
          return false;
        }
      }

      // 3. Date filtering - Apply both shared period filter and card-specific finer filter
      const txDate = new Date(tx.created_at);

      // Apply shared global dashboard date range
      if (dbStartDate && txDate.getTime() < new Date(dbStartDate).getTime()) {
        return false;
      }
      if (dbEndDate && txDate.getTime() > new Date(dbEndDate).setHours(23, 59, 59, 999)) {
        return false;
      }

      // Apply finer company margin card filter
      if (pdgMarginStartDate && txDate.getTime() < new Date(pdgMarginStartDate).getTime()) {
        return false;
      }
      if (pdgMarginEndDate && txDate.getTime() > new Date(pdgMarginEndDate).setHours(23, 59, 59, 999)) {
        return false;
      }

      return true;
    });

    return confirmedWithdrawals.reduce((sum, tx) => {
      const fee = tx.withdrawal_fee || Math.round(tx.amount * 0.03);
      return sum + fee;
    }, 0);
  };

  const loadSystemData = () => {
    try {
      const bFilter: BranchID | undefined =
        selectedBranch === "all" ? undefined : selectedBranch;

      // Profiles
      const profs = dbService.getProfiles(user, bFilter);
      setAllProfiles(profs);

      // Transactions with RLS
      const txs = dbService.getTransactions(user, bFilter);
      setAllTxns(txs);

      // Cached balances
      const fb = dbService.getClientBalances(user);
      setAllBalances(
        selectedBranch === "all"
          ? fb
          : fb.filter((x) => x.branch_id === selectedBranch),
      );

      // Loans lists
      const lns = dbService.getLoans(user, bFilter);
      setAllLoans(lns);

      // Audit registries
      try {
        const logs = dbService.getAuditTrail(user, bFilter);
        setAuditLogs(logs);
      } catch (auditErr) {
        console.warn("Audit trail loading deferred or restricted:", auditErr);
        setAuditLogs([]);
      }

      // Grants lists
      if (user.role === "pdg") {
        setAllTxns(dbService.getTransactions(user, bFilter)); // Overrides global PDG listings but respects branch scoping
        setActiveGrants(dbService.getGrantsAll());
      }

      // commission payouts
      setPayouts(dbService.getCommissionPayouts(user));
      setPayoutRequests(dbService.getPayoutRequests(user));
      setCommissionRates(dbService.getCommissionRates(user));
      setPolicyLimits(dbService.getPolicyLimits(user));
      setDepositCorrectionRequests(dbService.getDepositCorrectionRequests(user));
      setAllLeaves(dbService.getAgentLeaves(user));
      setIdValidationSettingsState(dbService.getIdValidationSettings());

      // Marathon data loading
      const fetchedMarathons = dbService.getMarathons(user);
      setMarathons(fetchedMarathons);
      
      const activeOrPaused = fetchedMarathons.find(m => m.status === "active" || m.status === "paused");
      const proposed = fetchedMarathons.find(m => m.status === "pending_approval");
      let mIdForDefinitions = selectedMarathonId;
      if (!mIdForDefinitions) {
        if (activeOrPaused) {
          mIdForDefinitions = activeOrPaused.id;
        } else if (proposed) {
          mIdForDefinitions = proposed.id;
        }
      }
      if (mIdForDefinitions) {
        setBadgeDefinitions(dbService.getBadgeDefinitions(user, mIdForDefinitions));
      } else {
        setBadgeDefinitions([]);
      }
      setBadgeAwards(dbService.getAgentBadgeAwards(user, selectedMarathonId || undefined));

      // notifications
      const fetchedNotifications = dbService.getNotifications(user);

      // Determine if a new notification arrived
      if (notifications.length > 0) {
        const oldUnreadIds = new Set(notifications.filter(n => !n.is_read).map(n => n.id));
        const newUnreadList = fetchedNotifications.filter(n => !n.is_read);
        const newlyArrivedUnread = newUnreadList.filter(n => !oldUnreadIds.has(n.id));

        if (newlyArrivedUnread.length > 0) {
          const hasNewLoanAlert = newlyArrivedUnread.some(
            (n) => n.type === "loan_approval_required" || n.type === "loan_escalated_to_hq"
          );
          if (hasNewLoanAlert) {
            playLoanNotificationSound();
          } else {
            playGeneralNotificationSound();
          }
        }
      }

      setNotifications(fetchedNotifications);
    } catch (err: any) {
      showBanner("RLS Access restriction: " + err.message, "error");
    }
  };

