  const handleResolveCorrection = async (requestId: string, status: "approved" | "rejected") => {
    try {
      if (status === "approved") {
        const amt = parseInt(activeCorrectionAmount, 10);
        if (isNaN(amt) || amt <= 0) {
          showBanner("Please specify a valid positive amount.", "error");
          return;
        }
        await dbService.resolveDepositCorrection(user, requestId, "approved", amt);
        showBanner("Deposit correction approved and applied successfully.", "success");
      } else {
        if (!activeCorrectionRejection.trim()) {
          showBanner("Please provide a rejection reason.", "error");
          return;
        }
        await dbService.resolveDepositCorrection(user, requestId, "rejected", undefined, activeCorrectionRejection.trim());
        showBanner("Deposit correction request rejected successfully.", "success");
      }
      setActiveCorrectionId(null);
      setCorrectionActionType(null);
      setActiveCorrectionAmount("");
      setActiveCorrectionRejection("");
      loadSystemData();
    } catch (err: any) {
      showBanner(err.message || "Failed.", "error");
    }
  };

