  const handleRegisterClientAdmin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (
      !regFullName.trim() ||
      !regPhone.trim() ||
      !regId.trim() ||
      !regLocality.trim() ||
      !regIssuedDate
    ) {
      showBanner(
        "ID Card Fraud Prevention: All registration fields, including date of issuance, are required.",
        "error",
      );
      return;
    }

    setIsRegisteringClient(true);
    try {
      if (editingClientProfile) {
        let clientBranchId = editingClientProfile.branch_id;
        const mapped = STATIC_BRANCHES.find(
          (b) => b.name.toLowerCase() === regSubdiv.toLowerCase()
        );
        if (mapped) {
          clientBranchId = mapped.id;
        }

        if (regId.trim()) {
          const sanitizedId = regId.trim();
          const validation = validateNationalID(regDocType, sanitizedId, regIssuedDate, dbService.getIdValidationSettings());
          if (!validation.success) {
            showBanner(validation.error || "ID Card Fraud Prevention: Invalid National ID format.", "error");
            setIsRegisteringClient(false);
            return;
          }

          const duplicateId = allProfiles.find(
            (p) => p.national_id === sanitizedId && p.id !== editingClientProfile.id
          );
          if (duplicateId) {
            showBanner("ID Card Fraud Prevention: This National ID is already registered to another member.", "error");
            setIsRegisteringClient(false);
            return;
          }
        }

        await dbService.updateProfile(user, editingClientProfile.id, {
          full_name: regFullName,
          phone: regPhone,
          national_id: regId,
          national_id_document_type: regDocType,
          national_id_issued_date: regIssuedDate,
          birthday: regBday,
          subdivision: regSubdiv,
          branch_id: clientBranchId,
          locality: regLocality,
          has_app_access: !regNoAppAccess,
          photo_url: regPhotoUrl || undefined,
        });

        showBanner(
          "Client profile updated successfully.",
          "success"
        );

        setRegFullName("");
        setRegPhone("");
        setRegId("");
        setRegDocType("card");
        setRegIssuedDate("");
        setRegBday("");
        setRegLocality("");
        setRegNoAppAccess(false);
        setRegPhotoUrl("");
        setEditingClientProfile(null);
        setShowRegisterModal(false);
        loadSystemData();
      } else {
        const result = await dbService.registerClientByAgent(
          user,
          regFullName,
          regPhone,
          regId,
          regBday,
          regSubdiv,
          regLocality,
          undefined,
          undefined,
          undefined,
          !regNoAppAccess,
          regPhotoUrl,
          regDocType,
          regIssuedDate,
        );
        showBanner(
          strings.mem_client_registered_success,
          "success",
        );
        setRegFullName("");
        setRegPhone("");
        setRegId("");
        setRegDocType("card");
        setRegIssuedDate("");
        setRegBday("");
        setRegLocality("");
        setRegNoAppAccess(false);
        setRegPhotoUrl("");
        setShowRegisterModal(false);
        
        // Load and display temporary credentials modal
        setTempCredentials({
          full_name: result.profile.full_name,
          phone: result.profile.phone,
          tempPin: result.tempPin,
          unique_display_id: result.profile.unique_display_id || "",
          account_number: result.profile.account_number || "",
          agent_code: result.profile.agent_code || "",
          recruited_by: result.profile.recruited_by || ""
        });
        setShowTempCredentialsModal(true);
        
        loadSystemData();
      }
    } catch (err: any) {
      showBanner(err.message || strings.admin_reg_failed, "error");
    } finally {
      setIsRegisteringClient(false);
    }
  };

