  const syncBroadcastCandidates = (newRecipientType: "client" | "agent" | "branch_admin", newBranch: BranchID | "all") => {
    const branchIdToFilter = user.role === "pdg" ? newBranch : user.branch_id;
    const candidates = allProfiles.filter((p) => {
      if (p.role !== newRecipientType) return false;
      if (branchIdToFilter !== "all" && p.branch_id !== branchIdToFilter) return false;
      return true;
    });
    setBroadcastSelectedRecipientIds(candidates.map((p) => p.id));
  };

  const getBroadcastCandidates = () => {
    const branchIdToFilter = user.role === "pdg" ? broadcastSelectedBranch : user.branch_id;
    return allProfiles.filter((p) => {
      if (p.role !== broadcastRecipientType) return false;
      if (branchIdToFilter !== "all" && p.branch_id !== branchIdToFilter) return false;
      return true;
    });
  };

  useEffect(() => {
    if (activeMenu === "broadcasts" && allProfiles.length > 0) {
      const branchIdToFilter = user.role === "pdg" ? broadcastSelectedBranch : user.branch_id;
      const candidates = allProfiles.filter((p) => {
        if (p.role !== broadcastRecipientType) return false;
        if (branchIdToFilter !== "all" && p.branch_id !== branchIdToFilter) return false;
        return true;
      });
      setBroadcastSelectedRecipientIds((prev) => {
        const currentIds = candidates.map(c => c.id);
        if (JSON.stringify(prev) !== JSON.stringify(currentIds)) {
          return currentIds;
        }
        return prev;
      });
    }
  }, [activeMenu, allProfiles.length, broadcastRecipientType, broadcastSelectedBranch, user.branch_id, user.role]);

  useEffect(() => {
    if (!exportSelectedAgentId && allProfiles.length > 0) {
      const firstAgent = allProfiles.find((p) => p.role === "agent");
      if (firstAgent) {
        setExportSelectedAgentId(firstAgent.id);
      }
    }
  }, [allProfiles, exportSelectedAgentId]);

  const handleComposeBroadcastSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!broadcastTitle || !broadcastBody) {
      showBanner(strings.broadcast_fill_required_error || "Please fill in the title and description body for the circular.", "error");
      return;
    }

    if (broadcastSelectedRecipientIds.length === 0) {
      showBanner("Please select at least one recipient.", "error");
      return;
    }

    setIsBroadcasting(true);
    try {
      // Always create in-app broadcast notifications so the message is stored in history logs
      dbService.createNotificationForRecipients(
        broadcastSelectedRecipientIds,
        {
          type: "broadcast_message",
          title: `📣 Broad-Alert: ${broadcastTitle}`,
          body: broadcastBody,
        }
      );

      // If SMS channel is toggled, additionally send out SMS text payloads
      if (broadcastChannel === "sms") {
        const selectedRecipients = allProfiles.filter((p) => broadcastSelectedRecipientIds.includes(p.id));
        const broadcastText = `📣 NGACCUL Circular: ${broadcastTitle}\n${broadcastBody}`;
        
        const smsPromises = selectedRecipients.map((recipient) => {
          if (recipient.phone) {
            return fetch("/api/sms/send", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ phone: recipient.phone, message: broadcastText })
            }).catch(e => console.error("Broadcast SMS failed for:", recipient.phone, e));
          }
          return Promise.resolve();
        });
        await Promise.all(smsPromises);
      }

      showBanner(strings.broadcast_dispatched_success || "Circular broadcast successfully dispatched!", "success");
      setBroadcastTitle("");
      setBroadcastBody("");
      loadSystemData();
    } catch (err: any) {
      showBanner(err.message, "error");
    } finally {
      setIsBroadcasting(false);
    }
  };

  const handleSendTestSms = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!testSmsPhone.trim() || !testSmsMessage.trim()) {
      showBanner("Please enter a valid phone number and message.", "error");
      return;
    }
    setTestSmsLoading(true);
    setTestSmsResult(null);
    try {
      const response = await fetch("/api/sms/send", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          phone: testSmsPhone,
          message: testSmsMessage,
        }),
      });
      const data = await response.json();
      if (response.ok) {
        setTestSmsResult({
          success: data.success,
          simulated: data.simulated,
          raw: data.raw,
          provider: data.provider,
        });
        if (data.success) {
          showBanner("SMS request processed successfully!", "success");
        } else {
          showBanner("SMS Gateway returned an error status.", "error");
        }
      } else {
        setTestSmsResult({
          success: false,
          simulated: false,
          error: data.details || data.error || "HTTP Error " + response.status,
          raw: data
        });
        showBanner(data.error || "Failed to communicate with SMS server", "error");
      }
    } catch (err: any) {
      console.error("[Test SMS Exception]", err);
      setTestSmsResult({
        success: false,
        simulated: false,
        error: err.message || "Network request failed",
      });
      showBanner("Failed to send test SMS: " + err.message, "error");
    } finally {
      setTestSmsLoading(false);
    }
  };

  const handlePerAgentClientBalancesExport = async (mode: "download" | "print" = "download") => {
    try {
      let filteredBalances = [...allBalances];
      if (dbStartDate) {
        const startMs = new Date(dbStartDate).getTime();
        filteredBalances = filteredBalances.filter(
          (b) => new Date(b.updated_at).getTime() >= startMs
        );
      }
      if (dbEndDate) {
        const endMs = new Date(dbEndDate).setHours(23, 59, 59, 999);
        filteredBalances = filteredBalances.filter(
          (b) => new Date(b.updated_at).getTime() <= endMs
        );
      }

      const clientProfiles = allProfiles.filter((p) => p.role === "client");
      const agentProfiles = allProfiles.filter((p) => p.role === "agent");

      const groupedData: {
        agentId: string;
        agentName: string;
        clients: {
          name: string;
          displayId: string;
          balance: number;
          totalDeposits: number;
          totalWithdrawals: number;
          lastUpdated: string;
        }[];
      }[] = [];

      const agentMap = new Map<string, string>();
      agentProfiles.forEach((a) => {
        agentMap.set(a.id, a.full_name);
      });

      filteredBalances.forEach((bal) => {
        const client = clientProfiles.find((c) => c.id === bal.client_id);
        if (!client) return;

        const agentId = client.recruited_by || "unassigned";
        const agentName = agentId === "unassigned" ? "Unassigned / Direct" : (agentMap.get(agentId) || "Unknown DC");

        let group = groupedData.find((g) => g.agentId === agentId);
        if (!group) {
          group = { agentId, agentName, clients: [] };
          groupedData.push(group);
        }

        group.clients.push({
          name: client.full_name || "Unknown",
          displayId: client.unique_display_id || "N/A",
          balance: Number(bal.balance) || 0,
          totalDeposits: Number(bal.total_deposits) || 0,
          totalWithdrawals: Number(bal.total_withdrawals) || 0,
          lastUpdated: bal.updated_at ? new Date(bal.updated_at).toLocaleString() : "N/A",
        });
      });

      groupedData.sort((a, b) => a.agentName.localeCompare(b.agentName));

      const sheetsSpec: NestedExcelSheetSpec[] = [{
        sheetName: "DC Balances",
        columnHeaders: [
          "Client Name",
          "Unique Display ID",
          "Balance (FCFA)",
          "Total Deposits (FCFA)",
          "Total Withdrawals (FCFA)",
          "Last Updated"
        ],
        sections: groupedData.map((group) => {
          group.clients.sort((a, b) => a.name.localeCompare(b.name));
          
          let agentTotalBalance = 0;
          let agentTotalDeposits = 0;
          let agentTotalWithdrawals = 0;

          const clientRows = group.clients.map((c) => {
            agentTotalBalance += c.balance;
            agentTotalDeposits += c.totalDeposits;
            agentTotalWithdrawals += c.totalWithdrawals;

            return [
              String(c.name).trim(),
              String(c.displayId).trim(),
              c.balance,
              c.totalDeposits,
              c.totalWithdrawals,
              String(c.lastUpdated).trim()
            ];
          });

          // Append styled subtotal row
          clientRows.push([
            `SUBTOTAL (${String(group.agentName).trim()})`,
            "",
            agentTotalBalance,
            agentTotalDeposits,
            agentTotalWithdrawals,
            ""
          ]);

          return {
            headerLabel: `DC: ${String(group.agentName).trim()}`,
            headerSubLabel: `${group.clients.length} Client(s) — Subtotal Balance: ${agentTotalBalance.toLocaleString()} FCFA`,
            rows: clientRows
          };
        })
      }];

      const dateSuffix = new Date().toISOString().slice(0, 10);
      await exportPDF(sheetsSpec, `Agent_Client_Balances_${dateSuffix}.pdf`, { mode });

      showBanner(mode === "print" ? "Preparing PDF for printing..." : "Per-agent client balances exported as PDF successfully.", "success");
    } catch (err: any) {
      console.error("Agent balances export failed:", err);
      showBanner(`Export failed: ${err.message}`, "error");
    }
  };

  const handlePerAgentWithdrawalsExport = async (mode: "download" | "print" = "download") => {
    try {
      if (!exportSelectedAgentId) {
        showBanner("Please select an agent first.", "error");
        return;
      }

      const agentProfile = allProfiles.find((p) => p.id === exportSelectedAgentId);
      const agentName = agentProfile ? agentProfile.full_name : "Unknown DC";

      const clientIds = allProfiles
        .filter((p) => p.role === "client" && p.recruited_by === exportSelectedAgentId)
        .map((p) => p.id);

      let withdrawals = allTxns.filter(
        (t) => t.type === "withdrawal" && clientIds.includes(t.client_id)
      );

      if (dbStartDate) {
        const startMs = new Date(dbStartDate).getTime();
        withdrawals = withdrawals.filter(
          (t) => new Date(t.created_at).getTime() >= startMs
        );
      }
      if (dbEndDate) {
        const endMs = new Date(dbEndDate).setHours(23, 59, 59, 999);
        withdrawals = withdrawals.filter(
          (t) => new Date(t.created_at).getTime() <= endMs
        );
      }

      let totalAmount = 0;
      let totalFee = 0;
      let totalNet = 0;

      const dataRows = withdrawals.map((tx) => {
        const client = allProfiles.find((p) => p.id === tx.client_id);
        const amount = Number(tx.amount) || 0;
        const fee = Number(tx.withdrawal_fee ?? Math.round(amount * 0.03));
        const net = Number(tx.net_payout ?? (amount - fee));

        totalAmount += amount;
        totalFee += fee;
        totalNet += net;

        return [
          client?.full_name || "Unknown",
          client?.unique_display_id || "N/A",
          amount,
          fee,
          net,
          tx.status.toUpperCase(),
          tx.created_at ? new Date(tx.created_at).toLocaleString() : "N/A"
        ];
      });

      // Append Total Row
      dataRows.push([
        "TOTAL",
        "",
        totalAmount,
        totalFee,
        totalNet,
        "",
        ""
      ]);

      const sheetsSpec: NestedExcelSheetSpec[] = [{
        sheetName: "Withdrawals",
        columnHeaders: [
          "Client Name",
          "Unique Display ID",
          "Withdrawal Amount (FCFA)",
          "Fee (3%) (FCFA)",
          "Net Payout (FCFA)",
          "Status",
          "Date"
        ],
        sections: [{
          headerLabel: `DC: ${agentName.trim()}`,
          headerSubLabel: `${withdrawals.length} Withdrawal(s) — Total Payout: ${totalNet.toLocaleString()} FCFA`,
          rows: dataRows
        }]
      }];

      const dateSuffix = new Date().toISOString().slice(0, 10);
      await exportPDF(sheetsSpec, `Agent_Withdrawals_${agentName.replace(/\s+/g, "_")}_${dateSuffix}.pdf`, { mode });

      showBanner(mode === "print" ? "Preparing PDF for printing..." : "DC withdrawals report exported as PDF successfully.", "success");
    } catch (err: any) {
      console.error("Agent withdrawals export failed:", err);
      showBanner(`Export failed: ${err.message}`, "error");
    }
  };

