  const handleSetBadgeDef = async (e: React.FormEvent) => {
    e.preventDefault();
    const activeOrPaused = marathons.find(m => m.status === "active" || m.status === "paused");
    if (!activeOrPaused) {
      showBanner(strings.marathon_no_selected_campaign_error || "No active or paused marathon campaign found.", "error");
      return;
    }
    const minClients = parseInt(newDefMinClients);
    const bonus = parseInt(newDefBonus);
    if (isNaN(minClients) || minClients <= 0) {
      showBanner(strings.marathon_hero_quota_invalid_error || "Please supply a valid positive minimum client quota.", "error");
      return;
    }
    if (isNaN(bonus) || bonus <= 0) {
      showBanner(strings.marathon_hero_bonus_invalid_error || "Please supply a valid positive bonus amount in FCFA.", "error");
      return;
    }
    try {
      dbService.setBadgeDefinition(user, activeOrPaused.id, newDefBranch === "all" ? null : newDefBranch, newDefTier, minClients, bonus);
      showBanner(
        newDefTier === "hero"
          ? (strings.marathon_hero_def_set_success || "HERO Badge configuration set successfully (new versioned entry created)!")
          : (strings.marathon_elite_def_set_success || "ELITE Badge configuration set successfully (new versioned entry created)!"),
        "success"
      );
      setNewDefMinClients("");
      setNewDefBonus("");
      loadSystemData();
    } catch (err: any) {
      showBanner(err.message, "error");
    }
  };

