                  <div className="text-xs text-brand-primary/75 bg-brand-primary/5 p-2 rounded-xl border border-brand-secondary/10 flex justify-between items-center mt-1">
                    <span>Computed Guarantor ID Expiry:</span>
                    <span className="font-bold font-numeric text-brand-primary">
                      {(() => {
                        const date = new Date(agentGuarantorIdIssuedDate);
                        if (!isNaN(date.getTime())) {
                          if (agentGuarantorIdDocType === 'card') {
                            date.setFullYear(date.getFullYear() + 10);
                          } else {
                            date.setMonth(date.getMonth() + 3);
                          }
                          return date.toISOString().split('T')[0];
                        }
                        return '';
                      })()}
                    </span>
                  </div>
